/**
 * Balsamiq Sans, Latin subset, weights 400 and 700, as WOFF2.
 * Copyright 2011 The Balsamiq Sans Project Authors (https://github.com/balsamiq/balsamiqsans).
 * Licensed under the SIL Open Font License 1.1: see ./fonts/OFL.txt.
 * Embedded as base64 so every build (source, bundle, native binary) serves it.
 */
const decode = (b64: string): Uint8Array => Uint8Array.from(Buffer.from(b64, 'base64'));

export const FONTS: Record<string, Uint8Array> = {
  'balsamiq-sans-400.woff2': decode(''),
  'balsamiq-sans-700.woff2': decode(''),
};
